def migrate_supplier_names(apps, schema_editor):
    Supplier = apps.get_model("accounts", "Supplier")
    cache = {}

    def supplier_for(name):
        name = name.strip()
        if not name:
            return None
        if name not in cache:
            cache[name], _ = Supplier.objects.get_or_create(name=name)
        return cache[name]

    for model_name in MODELS + HISTORICAL_MODELS:
        Model = apps.get_model("inputs", model_name)
        for row in Model.objects.exclude(supplier_name=""):
            supplier = supplier_for(row.supplier_name)
            if supplier is not None:
                row.supplier = supplier
                row.save(update_fields=["supplier"])


